import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

// In-process fake of the downstream pricing service (unit price in euros per sku).
const prices = { A: 10, B: 40, C: 100, D: 100.01, E: 101, F: 0.1, G: 33.33 }
const pricing = { async priceOf(sku) { return prices[sku] } }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST', headers: { 'content-type': 'application/json' }, body: raw ?? JSON.stringify(body),
})
const totalOf = async (items) => {
  const res = await post({ items })
  assert.equal(res.status, 201)
  assert.equal(res.headers.get('content-type'), 'application/json')
  return (await res.json()).total
}

test('POST /orders returns 201 with id, items and total', async () => {
  const items = [{ sku: 'A', qty: 2 }]
  const res = await post({ items })
  assert.equal(res.status, 201)
  const order = await res.json()
  assert.match(order.id, /^\d+$/)
  assert.deepEqual(order.items, items)
  assert.equal(order.total, 20)
})

test('ids are sequential strings', async () => {
  const a = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  const b = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('total sums price * qty over all items', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 2 }, { sku: 'B', qty: 1 }]), 60)
})

test('no discount at or below 100 (threshold is strictly greater than 100)', async () => {
  assert.equal(await totalOf([{ sku: 'C', qty: 1 }]), 100)
  assert.equal(await totalOf([{ sku: 'B', qty: 2 }]), 80)
})

test('10% discount above 100', async () => {
  assert.equal(await totalOf([{ sku: 'B', qty: 3 }]), 108) // 120
  assert.equal(await totalOf([{ sku: 'C', qty: 2 }]), 180) // 200
  assert.equal(await totalOf([{ sku: 'C', qty: 10 }]), 900) // 1000
})

test('discounted totals are floored to whole euros, not rounded', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — 101 * 0.9 = 90.9 is truncated to 90, and cents are always dropped
  assert.equal(await totalOf([{ sku: 'E', qty: 1 }]), 90)
  // CHARACTERIZATION: current behaviour may be unintended — 100.01 -> 90.009 -> 90
  assert.equal(await totalOf([{ sku: 'D', qty: 1 }]), 90)
})

test('undiscounted totals are floored too', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — 3 * 33.33 = 99.99 reported as 99 (cents lost)
  assert.equal(await totalOf([{ sku: 'G', qty: 3 }]), 99)
  // CHARACTERIZATION: current behaviour may be unintended — 0.1 * 3 is 0.30000000000000004, floored to 0
  assert.equal(await totalOf([{ sku: 'F', qty: 3 }]), 0)
})

test('discount applies to the whole order total, not per line', async () => {
  assert.equal(await totalOf([{ sku: 'B', qty: 2 }, { sku: 'A', qty: 3 }]), 99) // 110 * 0.9
})

test('unknown sku (undefined price) yields a null total', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — NaN total serialises as null, order still created
  const res = await post({ items: [{ sku: 'ZZZ', qty: 1 }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, null)
})

test('negative and zero quantities are accepted', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — no qty validation
  assert.equal(await totalOf([{ sku: 'A', qty: 0 }]), 0)
  assert.equal(await totalOf([{ sku: 'A', qty: -1 }]), -10)
})

test('POST /orders rejects missing, empty, non-array items and bad JSON with 400', async () => {
  for (const body of [{}, { items: [] }, { items: 'x' }]) {
    const res = await post(body)
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
  const bad = await post(null, '{not json')
  assert.equal(bad.status, 400)
  assert.deepEqual(await bad.json(), { error: 'items required' })
})

test('GET /orders/:id returns the stored order', async () => {
  const created = await (await post({ items: [{ sku: 'C', qty: 2 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), created)
})

test('GET /orders/:id for an unknown id answers 200 with an error body', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — "not found" is returned with status 200, not 404
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unknown routes and methods answer 404 no route', async () => {
  for (const [method, path] of [['GET', '/nope'], ['GET', '/orders'], ['DELETE', '/orders/1'], ['POST', '/orders/1']]) {
    const res = await fetch(`${base}${path}`, { method })
    assert.equal(res.status, 404)
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})
EOF
